// F4-03: un solo subflujo para los tres motivos de revisión manual, sin consumir ronda.
// F6-03: enmascara PII del texto libre y muestra nombre/razon social parciales.
const limpiar = (t) => String(t === null || t === undefined ? '' : t)
  .replace(/[\w.+-]+@[\w-]+\.[\w.]+/g, '<correo>')
  .replace(/https?:\/\/\S+/g, '<url>')
  .replace(/\b\d{7,}\b/g, '<num>');
const parcial = (t) => { const s = String(t === null || t === undefined ? '' : t).trim(); return s.length > 3 ? s.slice(0, 3) + '…' : s; };
const get = (name) => { try { return $(name).first().json || {}; } catch (e) { return {}; } };
const entrada = $json || {};
const ctx = entrada.contexto || {};
const nombre = entrada.nombre_cliente || ctx.nombre_cliente || '';
const razon = entrada.razon_social || ctx.razon_social || '';
const servicio = entrada.servicio || ctx.servicio || 'servicio';
const pdf = entrada.pdf_url || ctx.pdf_url || '(sin documento)';
const id = entrada.id_solicitud || ctx.id_solicitud || '';
const comentario = entrada.Comentario || entrada.comentario || ctx.Comentario || '';
const ronda = Number(entrada.ronda_correccion || ctx.ronda_correccion) || 0;
const conf = String(entrada.confianza || '');
const cfg = (() => { try { return $('Ejecutar Leer Configuración').first().json._config || {}; } catch (e) { return {}; } })();
const iaHabilitada = String(cfg.ia_correccion_habilitada || 'true') !== 'false';
// F7-03: tambien se llega aca cuando el asesor no aprueba la correccion propuesta por la IA.
const motivo = (entrada.aprobado === false) ? 'aprobacion_rechazada'
  : (ronda >= 3 ? 'tope' : (!iaHabilitada ? 'ia_desactivada' : 'confianza_baja'));
let asunto, cuerpo;
if (motivo === 'tope') {
  asunto = '[Propuesta CCB] Tope de correcciones alcanzado — ' + servicio + ' (' + id + ')';
  cuerpo = 'Se alcanzó el tope de 3 rondas de corrección para la propuesta de ' + parcial(nombre || 'cliente')
    + ' (' + parcial(razon || '-') + '). Requiere revisión manual.'
    + '\n\nComentario del asesor: ' + limpiar(comentario || '(sin comentario)')
    + '\n\nDocumento: ' + pdf;
} else {
  const detalle = motivo === 'aprobacion_rechazada'
    ? 'El asesor no aprobó el ajuste propuesto por la IA (o no respondió a tiempo).'
    : motivo === 'ia_desactivada'
    ? 'La corrección asistida por IA está desactivada por configuración.'
    : ('La IA interpretó el pedido con confianza ' + (conf || 'baja') + '; no se aplicó ningún ajuste automáticamente.');
  asunto = '[Propuesta CCB] Corrección pendiente de revisión manual — ' + servicio + ' (' + id + ')';
  cuerpo = '<p>La solicitud de correcciones <b>no se aplicó automáticamente</b>.</p><ul>'
    + '<li><b>Solicitud:</b> ' + id + '</li>'
    + '<li><b>Motivo:</b> ' + detalle + '</li>'
    + '<li><b>Interpretación de la IA:</b> ' + (entrada.resumen_cambios || '(sin resumen)') + '</li>'
    + '<li><b>Comentario del asesor:</b> ' + (comentario || '(sin comentario)') + '</li></ul>'
    + '<p>La propuesta queda en <b>revisión manual</b> y <b>no consumió una ronda</b> de corrección.</p>';
}
return { json: { ...entrada, id_solicitud: id, Comentario: comentario, motivo,
                 _aviso_asunto: asunto, _aviso_cuerpo: cuerpo } };

// F4-03/F7-03: el motivo se lee del nodo que arma el aviso.
const aviso = (() => { try { return $('Preparar aviso - Revisión manual').first().json || {}; } catch (e) { return {}; } })();
const mensaje = aviso.motivo === 'tope'
  ? 'Se alcanzó el máximo de 3 rondas de corrección. La propuesta queda en revisión manual y te vamos a contactar directamente.'
  : (aviso.motivo === 'aprobacion_rechazada'
     ? 'La corrección no fue aprobada. La propuesta queda en revisión manual y no se consumió una ronda.'
     : 'La corrección quedó pendiente de revisión manual; no se consumió una ronda.');
return { json: { ok: true, mensaje } };

